import sys
import math

def isPrime(num: int) -> int:
    if num < 2:
        return 0
    if num == 2:
        return 1
    if num % 2 == 0:
        return 0
    limit = int(math.isqrt(num))
    for i in range(3, limit + 1, 2):
        if num % i == 0:
            return 0
    return 1

def main():
    data = sys.stdin.read().strip()
    if not data:
        return
    N = int(data)
    primes = []
    for i in range(2, N + 1):
        if isPrime(i):
            primes.append(str(i))
    if primes:
        sys.stdout.write(' '.join(primes))

if __name__ == "__main__":
    main()
